//! Holds the per-object parity claim: this pipeline's nuclei against QuPath's,
//! by Dice over the pixel masks, on real tissue.
//!
//! Fixture generated by `parity/java/.../RecordObjectMasks.java` via
//! `./parity/record-object-masks.sh`, which needs a slide.
//!
//! **Why this test and not just the count.** Every other detection figure here
//! is a count, and `README.md` says outright that a matching count is the
//! weakest evidence there is: two segmentations can agree on how many nuclei a
//! region holds while disagreeing about which pixels each covers. This is the
//! assertion a count cannot make.
//!
//! **What is thresholded, and why so loosely.** The measured pooled Dice is
//! 0.935, 0.934 and 0.880 over the three regions, and the floors below sit well
//! under those. That is deliberate: this is a **regression** gate, not a record
//! of the best number reached. A floor set at the measurement would fail on any
//! change to a rounding boundary and teach the next reader to raise it rather
//! than to look; a floor at 0.80 fails only if something real broke. The
//! measurement itself is printed by `examples/object_masks`, which is where the
//! number to quote comes from.
//!
//! **No seam can reach this.** The recorded regions are 2048x2048 and fit one
//! tile, so `DIVERGENCES.md` D-008 — two overlap-resolution rules disagreeing —
//! is out of reach by construction. What this measures is detection against
//! detection.
//!
//! **Masks, not rasterised polygons.** Both sides are the pixels each pipeline
//! labelled; see `run_collecting_masks` for why comparing against a
//! rasterisation of our outline would compare the wrong thing.

use std::path::Path;

use qupath_pipeline::{Params, Region, run_collecting_masks};
use qupath_slide::Slide;

/// Pooled Dice must clear this in every region. See the module note: a
/// regression floor, not the measurement.
const DICE_FLOOR: f64 = 0.80;

/// And this fraction of QuPath's objects must find a partner overlapping at all.
const MATCHED_FLOOR: f64 = 0.90;

fn fixture() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../parity/fixtures/ObjectMasks.json")
}

fn slide() -> Option<Slide> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/CMU-1.svs");
    path.exists()
        .then(|| Slide::open(&path).expect("open the slide"))
}

fn field<'a>(text: &'a str, key: &str, from: usize) -> Option<(&'a str, usize)> {
    let needle = format!("\"{key}\":");
    let at = text[from..].find(&needle)? + from + needle.len();
    let rest = &text[at..];
    let trimmed = rest.trim_start();
    let lead = rest.len() - trimmed.len();
    let (value, len) = if let Some(inner) = trimmed.strip_prefix('"') {
        let end = inner.find('"').expect("closing quote");
        (&inner[..end], end + 2)
    } else {
        let end = trimmed.find([',', '}', ']', '\n']).unwrap_or(trimmed.len());
        (trimmed[..end].trim(), end)
    };
    Some((value, at + lead + len))
}

fn number(text: &str, key: &str, from: usize) -> (u32, usize) {
    let (value, at) = field(text, key, from).unwrap_or_else(|| panic!("{key} missing"));
    (
        value.parse().unwrap_or_else(|_| panic!("{key} numeric")),
        at,
    )
}

/// One recorded region: its rectangle, and every nucleus painted into a
/// region-sized label grid.
struct Painted {
    name: String,
    region: Region,
    grid: Vec<u32>,
    objects: usize,
}

fn parse(text: &str) -> Vec<Painted> {
    let mut out = Vec::new();
    let mut at = text.find("\"regions\"").expect("regions");
    while let Some((name, next)) = field(text, "name", at) {
        let name = name.to_owned();
        let (x, next) = number(text, "x", next);
        let (y, next) = number(text, "y", next);
        let (width, next) = number(text, "width", next);
        let (height, next) = number(text, "height", next);
        let (nuclei, next) = number(text, "nuclei", next);
        let (_total, next) = number(text, "areaTotal", next);

        let mut grid = vec![0u32; (width as usize) * (height as usize)];
        let mut cursor = next;
        for object in 0..nuclei {
            let (ox, c) = number(text, "x", cursor);
            let (oy, c) = number(text, "y", c);
            let (ow, c) = number(text, "w", c);
            let (oh, c) = number(text, "h", c);
            let (area, c) = number(text, "area", c);
            let (mask, c) = field(text, "mask", c).expect("mask");
            let bytes: Vec<u8> = (0..mask.len() / 2)
                .map(|i| u8::from_str_radix(&mask[i * 2..i * 2 + 2], 16).expect("hex byte"))
                .collect();
            assert_eq!(
                bytes.len(),
                ((ow * oh) as usize).div_ceil(8),
                "mask length must match the bounding box"
            );
            // The recorder writes `area` as the popcount. Checking it means a
            // packing that drifted is caught here rather than showing up as a
            // low Dice that reads as a detection difference.
            let popcount: u32 = bytes.iter().map(|b| b.count_ones()).sum();
            assert_eq!(popcount, area, "recorded area must be the mask's popcount");
            for row in 0..oh {
                for column in 0..ow {
                    let bit = (row * ow + column) as usize;
                    if bytes[bit / 8] & (1 << (bit % 8)) == 0 {
                        continue;
                    }
                    let (gx, gy) = (ox + column, oy + row);
                    if gx < width && gy < height {
                        grid[gy as usize * width as usize + gx as usize] = object + 1;
                    }
                }
            }
            cursor = c;
        }
        out.push(Painted {
            name,
            region: Region {
                x,
                y,
                width,
                height,
            },
            grid,
            objects: nuclei as usize,
        });
        at = cursor;
    }
    out
}

#[test]
fn every_region_agrees_with_qupath_pixel_for_pixel_within_the_floor() {
    let text = match std::fs::read_to_string(fixture()) {
        Ok(text) => text,
        Err(_) => {
            qupath_testing::skipped("parity/fixtures/ObjectMasks.json not recorded");
            return;
        }
    };
    let Some(slide) = slide() else {
        qupath_testing::skipped("data/CMU-1.svs not present");
        return;
    };

    let regions = parse(&text);
    assert!(!regions.is_empty(), "the fixture records no regions");

    for painted in &regions {
        let (_outcome, ours) = run_collecting_masks(&slide, painted.region, Params::default())
            .expect("run the pipeline");
        assert!(
            ours.has_masks(),
            "without masks the comparison below would compare nothing and pass"
        );

        let width = painted.region.width as usize;
        let mut mine = vec![0u32; painted.grid.len()];
        for (object, bounds) in ours.bounds().iter().enumerate() {
            let mask = ours.mask(object).expect("masks were asked for");
            let (bx, by) = (bounds.x - painted.region.x, bounds.y - painted.region.y);
            for row in 0..bounds.height {
                for column in 0..bounds.width {
                    let bit = (row * bounds.width + column) as usize;
                    if mask[bit / 64] & (1u64 << (bit % 64)) == 0 {
                        continue;
                    }
                    let (gx, gy) = (bx + column, by + row);
                    if gx < painted.region.width && gy < painted.region.height {
                        mine[gy as usize * width + gx as usize] =
                            u32::try_from(object + 1).expect("fits u32");
                    }
                }
            }
        }

        let (mut ours_px, mut theirs_px, mut shared) = (0u64, 0u64, 0u64);
        let mut hit = vec![false; painted.objects];
        for (&a, &b) in mine.iter().zip(&painted.grid) {
            ours_px += u64::from(a != 0);
            theirs_px += u64::from(b != 0);
            if a != 0 && b != 0 {
                shared += 1;
                hit[b as usize - 1] = true;
            }
        }
        let dice = 2.0 * shared as f64 / (ours_px + theirs_px) as f64;
        let found = hit.iter().filter(|h| **h).count();
        let fraction = found as f64 / painted.objects as f64;

        assert!(
            dice >= DICE_FLOOR,
            "{}: pooled Dice {dice:.4} fell below {DICE_FLOOR}; \
             ours {ours_px} px against QuPath's {theirs_px} px, {shared} shared",
            painted.name
        );
        assert!(
            fraction >= MATCHED_FLOOR,
            "{}: only {found} of QuPath's {} nuclei overlap anything of ours ({fraction:.4})",
            painted.name,
            painted.objects
        );
    }
}
